insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096126', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, calcule a derivada de $f(x)=\frac{x+1}{x+3}$. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961261', '40000000-0000-4000-8000-000000096126', 'A', '$\frac{2}{(x+3)^2}$', 1), ('50000000-0000-4000-8000-000000961262', '40000000-0000-4000-8000-000000096126', 'B', '$\frac{1}{x+3}$', 2), ('50000000-0000-4000-8000-000000961263', '40000000-0000-4000-8000-000000096126', 'C', '$\frac{-2}{(x+3)^2}$', 3), ('50000000-0000-4000-8000-000000961264', '40000000-0000-4000-8000-000000096126', 'D', '$\frac{x+1}{(x+3)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096126', '50000000-0000-4000-8000-000000961261') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
