insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961291', '40000000-0000-4000-8000-000000096129', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961292', '40000000-0000-4000-8000-000000096129', 'Derive cada parcela independentemente.', 2), ('60000000-0000-4000-8000-000000961293', '40000000-0000-4000-8000-000000096129', 'Uma constante não varia quando a entrada muda.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096129', '$18x^2-1$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961291', '40000000-0000-4000-8000-000000096129', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961292', '40000000-0000-4000-8000-000000096129', 'Derive a potência', '$(6x^3)^{\\prime}=18x^2$.', 2), ('70000000-0000-4000-8000-000000961293', '40000000-0000-4000-8000-000000096129', 'Derive os termos restantes', '$(-1x)^{\\prime}=-1$ e $(4)^{\\prime}=0$.', 3), ('70000000-0000-4000-8000-000000961294', '40000000-0000-4000-8000-000000096129', 'Reúna os termos', '$f^{\\prime}(x)=18x^2-1$.', 4), ('70000000-0000-4000-8000-000000961295', '40000000-0000-4000-8000-000000096129', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
