insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096139', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961391', '40000000-0000-4000-8000-000000096139', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961392', '40000000-0000-4000-8000-000000096139', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000961393', '40000000-0000-4000-8000-000000096139', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096139', '$x=y=5$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961391', '40000000-0000-4000-8000-000000096139', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961392', '40000000-0000-4000-8000-000000096139', 'Use o perímetro', '$2x+2y=20 \Rightarrow y=10-x.$', 2), ('70000000-0000-4000-8000-000000961393', '40000000-0000-4000-8000-000000096139', 'Escreva a área', '$A(x)=x(10-x).$', 3), ('70000000-0000-4000-8000-000000961394', '40000000-0000-4000-8000-000000096139', 'Localize o vértice', '$A^{\prime}(x)=10-2x=0 \Rightarrow x=5, y=5.$', 4), ('70000000-0000-4000-8000-000000961395', '40000000-0000-4000-8000-000000096139', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096140', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e calcule a derivada de $f(x)=\frac{x+2}{x+5}$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961401', '40000000-0000-4000-8000-000000096140', 'A', '$\frac{3}{(x+5)^2}$', 1), ('50000000-0000-4000-8000-000000961402', '40000000-0000-4000-8000-000000096140', 'B', '$\frac{1}{x+5}$', 2), ('50000000-0000-4000-8000-000000961403', '40000000-0000-4000-8000-000000096140', 'C', '$\frac{-3}{(x+5)^2}$', 3), ('50000000-0000-4000-8000-000000961404', '40000000-0000-4000-8000-000000096140', 'D', '$\frac{x+2}{(x+5)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096140', '50000000-0000-4000-8000-000000961401') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096140', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961401', '40000000-0000-4000-8000-000000096140', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961402', '40000000-0000-4000-8000-000000096140', 'Use a regra do quociente: derivada do numerador vezes denominador, menos numerador vezes derivada do denominador.', 2), ('60000000-0000-4000-8000-000000961403', '40000000-0000-4000-8000-000000096140', 'As duas expressões lineares têm derivada igual a 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096140', '$f^{\prime}(x)=\frac{3}{(x+5)^2}.$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra do quociente exige atenção à ordem da subtração. Neste caso, as derivadas das duas expressões lineares são iguais a 1, então os termos com x se cancelam e resta apenas a diferença entre as constantes. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961401', '40000000-0000-4000-8000-000000096140', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961402', '40000000-0000-4000-8000-000000096140', 'Nomeie as partes', '$u=x+2, v=x+5 e u^{\prime}=v^{\prime}=1.$', 2), ('70000000-0000-4000-8000-000000961403', '40000000-0000-4000-8000-000000096140', 'Aplique a regra', '$f^{\prime}(x)=\frac{(x+5)-(x+2)}{(x+5)^2}.$', 3), ('70000000-0000-4000-8000-000000961404', '40000000-0000-4000-8000-000000096140', 'Simplifique', '$f^{\prime}(x)=\frac{3}{(x+5)^2}.$', 4), ('70000000-0000-4000-8000-000000961405', '40000000-0000-4000-8000-000000096140', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096141', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, calcule a derivada de $g(x)=(x^2+1)^3$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
