insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961501', '40000000-0000-4000-8000-000000096150', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961502', '40000000-0000-4000-8000-000000096150', 'Uma parábola com coeficiente negativo em x ao quadrado abre para baixo.', 2), ('60000000-0000-4000-8000-000000961503', '40000000-0000-4000-8000-000000096150', 'Encontre o ponto em que a derivada se anula.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096150', '$x=2$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma função quadrática com coeficiente principal negativo tem concavidade voltada para baixo; por isso, seu único ponto crítico é um máximo global. A derivada permite localizar esse ponto sem depender de um esboço do gráfico e confirma onde a taxa de variação muda de positiva para negativa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961501', '40000000-0000-4000-8000-000000096150', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961502', '40000000-0000-4000-8000-000000096150', 'Derive', '$f^{\prime}(x)=-2x+4.$', 2), ('70000000-0000-4000-8000-000000961503', '40000000-0000-4000-8000-000000096150', 'Encontre o crítico', '$-2x+4=0 \Rightarrow x=2.$', 3), ('70000000-0000-4000-8000-000000961504', '40000000-0000-4000-8000-000000096150', 'Classifique', '$f^{primeprime}(x)=-2<0,$ portanto é máximo.', 4), ('70000000-0000-4000-8000-000000961505', '40000000-0000-4000-8000-000000096150', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096151', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, se $f(x)=4x-3$, qual é $f^{-1}(x)$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
