insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961531', '40000000-0000-4000-8000-000000096153', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961532', '40000000-0000-4000-8000-000000096153', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000961533', '40000000-0000-4000-8000-000000096153', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096153', '$x=y=6$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961531', '40000000-0000-4000-8000-000000096153', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961532', '40000000-0000-4000-8000-000000096153', 'Use o perímetro', '$2x+2y=24 \Rightarrow y=12-x.$', 2), ('70000000-0000-4000-8000-000000961533', '40000000-0000-4000-8000-000000096153', 'Escreva a área', '$A(x)=x(12-x).$', 3), ('70000000-0000-4000-8000-000000961534', '40000000-0000-4000-8000-000000096153', 'Localize o vértice', '$A^{\prime}(x)=12-2x=0 \Rightarrow x=6, y=6.$', 4), ('70000000-0000-4000-8000-000000961535', '40000000-0000-4000-8000-000000096153', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096154', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, calcule a derivada de $f(x)=\frac{x+4}{x+1}$. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961541', '40000000-0000-4000-8000-000000096154', 'A', '$\frac{-3}{(x+1)^2}$', 1), ('50000000-0000-4000-8000-000000961542', '40000000-0000-4000-8000-000000096154', 'B', '$\frac{1}{x+1}$', 2), ('50000000-0000-4000-8000-000000961543', '40000000-0000-4000-8000-000000096154', 'C', '$\frac{3}{(x+1)^2}$', 3), ('50000000-0000-4000-8000-000000961544', '40000000-0000-4000-8000-000000096154', 'D', '$\frac{x+4}{(x+1)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
