insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096165', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961651', '40000000-0000-4000-8000-000000096165', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961652', '40000000-0000-4000-8000-000000096165', 'Exponencie os dois lados com base e.', 2), ('60000000-0000-4000-8000-000000961653', '40000000-0000-4000-8000-000000096165', 'Lembre que o logaritmo natural só aceita entradas positivas.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096165', '$x=e^{4}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961651', '40000000-0000-4000-8000-000000096165', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961652', '40000000-0000-4000-8000-000000096165', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 2), ('70000000-0000-4000-8000-000000961653', '40000000-0000-4000-8000-000000096165', 'Escreva a condição', '$e^{\ln(x)}=e^{4}$.', 3), ('70000000-0000-4000-8000-000000961654', '40000000-0000-4000-8000-000000096165', 'Faça o cálculo', '$x=e^{4}$.', 4), ('70000000-0000-4000-8000-000000961655', '40000000-0000-4000-8000-000000096165', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096166', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-110$, partindo de $x_0=11$. Qual é $x_1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961661', '40000000-0000-4000-8000-000000096166', 'A', '$\frac{231}{22}$', 1), ('50000000-0000-4000-8000-000000961662', '40000000-0000-4000-8000-000000096166', 'B', '$11$', 2), ('50000000-0000-4000-8000-000000961663', '40000000-0000-4000-8000-000000096166', 'C', '$10$', 3), ('50000000-0000-4000-8000-000000961664', '40000000-0000-4000-8000-000000096166', 'D', '$\frac{110}{11}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096166', '50000000-0000-4000-8000-000000961661') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096166', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961661', '40000000-0000-4000-8000-000000096166', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961662', '40000000-0000-4000-8000-000000096166', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000961663', '40000000-0000-4000-8000-000000096166', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096166', '$x_1=\frac{231}{22}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961661', '40000000-0000-4000-8000-000000096166', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961662', '40000000-0000-4000-8000-000000096166', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000961663', '40000000-0000-4000-8000-000000096166', 'Aplique Newton', '$x_1=11-\frac{121-110}{2\cdot 11}.$', 3), ('70000000-0000-4000-8000-000000961664', '40000000-0000-4000-8000-000000096166', 'Simplifique', '$x_1=\frac{231}{22}.$', 4), ('70000000-0000-4000-8000-000000961665', '40000000-0000-4000-8000-000000096166', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096167', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, um retângulo tem perímetro 28 m. Qual deve ser a medida de cada lado para que sua área seja máxima?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961671', '40000000-0000-4000-8000-000000096167', 'A', '$7$ m', 1), ('50000000-0000-4000-8000-000000961672', '40000000-0000-4000-8000-000000096167', 'B', '$9$ m', 2), ('50000000-0000-4000-8000-000000961673', '40000000-0000-4000-8000-000000096167', 'C', '$4$ m', 3), ('50000000-0000-4000-8000-000000961674', '40000000-0000-4000-8000-000000096167', 'D', '$14$ m', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096167', '50000000-0000-4000-8000-000000961671') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096167', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961671', '40000000-0000-4000-8000-000000096167', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961672', '40000000-0000-4000-8000-000000096167', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000961673', '40000000-0000-4000-8000-000000096167', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096167', '$x=y=7$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961671', '40000000-0000-4000-8000-000000096167', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961672', '40000000-0000-4000-8000-000000096167', 'Use o perímetro', '$2x+2y=28 \Rightarrow y=14-x.$', 2), ('70000000-0000-4000-8000-000000961673', '40000000-0000-4000-8000-000000096167', 'Escreva a área', '$A(x)=x(14-x).$', 3), ('70000000-0000-4000-8000-000000961674', '40000000-0000-4000-8000-000000096167', 'Localize o vértice', '$A^{\prime}(x)=14-2x=0 \Rightarrow x=7, y=7.$', 4), ('70000000-0000-4000-8000-000000961675', '40000000-0000-4000-8000-000000096167', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096168', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, calcule a derivada de $f(x)=\frac{x+3}{x+7}$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961681', '40000000-0000-4000-8000-000000096168', 'A', '$\frac{4}{(x+7)^2}$', 1), ('50000000-0000-4000-8000-000000961682', '40000000-0000-4000-8000-000000096168', 'B', '$\frac{1}{x+7}$', 2), ('50000000-0000-4000-8000-000000961683', '40000000-0000-4000-8000-000000096168', 'C', '$\frac{-4}{(x+7)^2}$', 3), ('50000000-0000-4000-8000-000000961684', '40000000-0000-4000-8000-000000096168', 'D', '$\frac{x+3}{(x+7)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096168', '50000000-0000-4000-8000-000000961681') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096168', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961681', '40000000-0000-4000-8000-000000096168', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961682', '40000000-0000-4000-8000-000000096168', 'Use a regra do quociente: derivada do numerador vezes denominador, menos numerador vezes derivada do denominador.', 2), ('60000000-0000-4000-8000-000000961683', '40000000-0000-4000-8000-000000096168', 'As duas expressões lineares têm derivada igual a 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096168', '$f^{\prime}(x)=\frac{4}{(x+7)^2}.$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra do quociente exige atenção à ordem da subtração. Neste caso, as derivadas das duas expressões lineares são iguais a 1, então os termos com x se cancelam e resta apenas a diferença entre as constantes. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961681', '40000000-0000-4000-8000-000000096168', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961682', '40000000-0000-4000-8000-000000096168', 'Nomeie as partes', '$u=x+3, v=x+7 e u^{\prime}=v^{\prime}=1.$', 2), ('70000000-0000-4000-8000-000000961683', '40000000-0000-4000-8000-000000096168', 'Aplique a regra', '$f^{\prime}(x)=\frac{(x+7)-(x+3)}{(x+7)^2}.$', 3), ('70000000-0000-4000-8000-000000961684', '40000000-0000-4000-8000-000000096168', 'Simplifique', '$f^{\prime}(x)=\frac{4}{(x+7)^2}.$', 4), ('70000000-0000-4000-8000-000000961685', '40000000-0000-4000-8000-000000096168', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096169', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, calcule a derivada de $g(x)=(x^2+3)^3$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961691', '40000000-0000-4000-8000-000000096169', 'A', '$6x(x^2+3)^2$', 1), ('50000000-0000-4000-8000-000000961692', '40000000-0000-4000-8000-000000096169', 'B', '$3(x^2+3)^2$', 2), ('50000000-0000-4000-8000-000000961693', '40000000-0000-4000-8000-000000096169', 'C', '$6x(x^2+3)^3$', 3), ('50000000-0000-4000-8000-000000961694', '40000000-0000-4000-8000-000000096169', 'D', '$2x(x^2+3)^2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
