insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961751', '40000000-0000-4000-8000-000000096175', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961752', '40000000-0000-4000-8000-000000096175', 'A substituição inicial dá zero sobre zero.', 2), ('60000000-0000-4000-8000-000000961753', '40000000-0000-4000-8000-000000096175', 'Multiplique pela expressão conjugada $\sqrt{x+8}+4$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096175', '$1/8$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A racionalização transforma a diferença de raízes em uma diferença de quadrados. Assim aparece o fator do denominador, que pode ser cancelado antes de avaliarmos a tendência no ponto. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961751', '40000000-0000-4000-8000-000000096175', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961752', '40000000-0000-4000-8000-000000096175', 'Use o conjugado', 'Multiplique numerador e denominador por $\sqrt{x+8}+4$.', 2), ('70000000-0000-4000-8000-000000961753', '40000000-0000-4000-8000-000000096175', 'Simplifique o numerador', '$(x+8)-16=x-8$.', 3), ('70000000-0000-4000-8000-000000961754', '40000000-0000-4000-8000-000000096175', 'Cancele e avalie', 'Resta $1/(\sqrt{x+8}+4)$, cujo limite é $1/8$.', 4), ('70000000-0000-4000-8000-000000961755', '40000000-0000-4000-8000-000000096175', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096176', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Em uma verificação de raciocínio, partindo de $y=x^2$, qual transformação produz $g(x)=(x-6)^2+5$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961761', '40000000-0000-4000-8000-000000096176', 'A', 'Deslocar 6 unidades à direita e 5 para cima.', 1), ('50000000-0000-4000-8000-000000961762', '40000000-0000-4000-8000-000000096176', 'B', 'Deslocar 6 unidades à esquerda e 5 para cima.', 2), ('50000000-0000-4000-8000-000000961763', '40000000-0000-4000-8000-000000096176', 'C', 'Deslocar 5 unidades à direita e 6 para cima.', 3), ('50000000-0000-4000-8000-000000961764', '40000000-0000-4000-8000-000000096176', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
