insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961831', '40000000-0000-4000-8000-000000096183', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961832', '40000000-0000-4000-8000-000000096183', 'Há uma função externa, o cubo, aplicada a uma função interna.', 2), ('60000000-0000-4000-8000-000000961833', '40000000-0000-4000-8000-000000096183', 'Multiplique a derivada da parte externa pela derivada de x ao quadrado mais n.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096183', '$g^{\prime}(x)=6x(x^2+4)^2$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961831', '40000000-0000-4000-8000-000000096183', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961832', '40000000-0000-4000-8000-000000096183', 'Defina a parte interna', '$u=x^2+4.$', 2), ('70000000-0000-4000-8000-000000961833', '40000000-0000-4000-8000-000000096183', 'Derive a parte externa', '$(u^3)^{\prime}=3u^2.$', 3), ('70000000-0000-4000-8000-000000961834', '40000000-0000-4000-8000-000000096183', 'Multiplique por u linha', '$g^{\prime}(x)=3(x^2+4)^2\cdot 2x=6x(x^2+4)^2.$', 4), ('70000000-0000-4000-8000-000000961835', '40000000-0000-4000-8000-000000096183', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096184', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, calcule a derivada de $f(x)=4x^{5}$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961841', '40000000-0000-4000-8000-000000096184', 'A', '$20x^4$', 1), ('50000000-0000-4000-8000-000000961842', '40000000-0000-4000-8000-000000096184', 'B', '$4x^4$', 2), ('50000000-0000-4000-8000-000000961843', '40000000-0000-4000-8000-000000096184', 'C', '$20x^5$', 3), ('50000000-0000-4000-8000-000000961844', '40000000-0000-4000-8000-000000096184', 'D', '$6x^4$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
