insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961991', '40000000-0000-4000-8000-000000096199', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961992', '40000000-0000-4000-8000-000000096199', 'A substituição direta produz a forma indeterminada zero sobre zero.', 2), ('60000000-0000-4000-8000-000000961993', '40000000-0000-4000-8000-000000096199', 'Fatore diferença de quadrados e simplifique antes de tomar o limite.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096199', '$16$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A forma zero sobre zero não é uma resposta: ela sinaliza que a expressão deve ser reorganizada. A diferença de quadrados revela um fator x menos a que pode ser cancelado fora do ponto problemático. Depois da simplificação, a função restante é contínua e pode ser avaliada diretamente no ponto de aproximação. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961991', '40000000-0000-4000-8000-000000096199', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961992', '40000000-0000-4000-8000-000000096199', 'Identifique a informação', 'Substituir 8 inicialmente gera zero sobre zero.', 2), ('70000000-0000-4000-8000-000000961993', '40000000-0000-4000-8000-000000096199', 'Escreva a condição', '$x^2-64=(x-8)(x+8)$.', 3), ('70000000-0000-4000-8000-000000961994', '40000000-0000-4000-8000-000000096199', 'Faça o cálculo', '$\frac{x^2-64}{x-8}=x+8,;x\ne8$.', 4), ('70000000-0000-4000-8000-000000961995', '40000000-0000-4000-8000-000000096199', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096200', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e partindo de $y=x^2$, qual transformação produz $g(x)=(x-8)^2+7$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962001', '40000000-0000-4000-8000-000000096200', 'A', 'Deslocar 8 unidades à direita e 7 para cima.', 1), ('50000000-0000-4000-8000-000000962002', '40000000-0000-4000-8000-000000096200', 'B', 'Deslocar 8 unidades à esquerda e 7 para cima.', 2), ('50000000-0000-4000-8000-000000962003', '40000000-0000-4000-8000-000000096200', 'C', 'Deslocar 7 unidades à direita e 8 para cima.', 3), ('50000000-0000-4000-8000-000000962004', '40000000-0000-4000-8000-000000096200', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
