insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096200', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962001', '40000000-0000-4000-8000-000000096200', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962002', '40000000-0000-4000-8000-000000096200', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000962003', '40000000-0000-4000-8000-000000096200', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096200', 'Deslocar 8 unidades à direita e 7 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962001', '40000000-0000-4000-8000-000000096200', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962002', '40000000-0000-4000-8000-000000096200', 'Identifique a informação', '$g(x)=(x-8)^2+7$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000962003', '40000000-0000-4000-8000-000000096200', 'Escreva a condição', '$x-8$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000962004', '40000000-0000-4000-8000-000000096200', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(8,7)$.', 4), ('70000000-0000-4000-8000-000000962005', '40000000-0000-4000-8000-000000096200', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096201', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, para qual valor de $c$ a função $f(x)=\begin{cases}x+9,&x<9\\c,&x\ge9\end{cases}$ é contínua em $x=9$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962011', '40000000-0000-4000-8000-000000096201', 'A', '$18$', 1), ('50000000-0000-4000-8000-000000962012', '40000000-0000-4000-8000-000000096201', 'B', '$9$', 2), ('50000000-0000-4000-8000-000000962013', '40000000-0000-4000-8000-000000096201', 'C', '$19$', 3), ('50000000-0000-4000-8000-000000962014', '40000000-0000-4000-8000-000000096201', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096201', '50000000-0000-4000-8000-000000962011') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096201', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962011', '40000000-0000-4000-8000-000000096201', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962012', '40000000-0000-4000-8000-000000096201', 'Para haver continuidade, o limite pela esquerda deve coincidir com o valor da função.', 2), ('60000000-0000-4000-8000-000000962013', '40000000-0000-4000-8000-000000096201', 'A expressão da esquerda vale x mais 9.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096201', '$c=18$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962011', '40000000-0000-4000-8000-000000096201', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962012', '40000000-0000-4000-8000-000000096201', 'Identifique a informação', 'O possível salto ocorre no ponto $x=9$.', 2), ('70000000-0000-4000-8000-000000962013', '40000000-0000-4000-8000-000000096201', 'Escreva a condição', '$lim_{x\to9^-}(x+9)=9+9$.', 3), ('70000000-0000-4000-8000-000000962014', '40000000-0000-4000-8000-000000096201', 'Faça o cálculo', '$lim_{x\to9^-}f(x)=18$.', 4), ('70000000-0000-4000-8000-000000962015', '40000000-0000-4000-8000-000000096201', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096202', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, para $f(x)=-x^2+12x$, em qual x ocorre o máximo global?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
