insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962111', '40000000-0000-4000-8000-000000096211', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962112', '40000000-0000-4000-8000-000000096211', 'A substituição direta produz a forma indeterminada zero sobre zero.', 2), ('60000000-0000-4000-8000-000000962113', '40000000-0000-4000-8000-000000096211', 'Fatore diferença de quadrados e simplifique antes de tomar o limite.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096211', '$18$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A forma zero sobre zero não é uma resposta: ela sinaliza que a expressão deve ser reorganizada. A diferença de quadrados revela um fator x menos a que pode ser cancelado fora do ponto problemático. Depois da simplificação, a função restante é contínua e pode ser avaliada diretamente no ponto de aproximação. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962111', '40000000-0000-4000-8000-000000096211', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962112', '40000000-0000-4000-8000-000000096211', 'Identifique a informação', 'Substituir 9 inicialmente gera zero sobre zero.', 2), ('70000000-0000-4000-8000-000000962113', '40000000-0000-4000-8000-000000096211', 'Escreva a condição', '$x^2-81=(x-9)(x+9)$.', 3), ('70000000-0000-4000-8000-000000962114', '40000000-0000-4000-8000-000000096211', 'Faça o cálculo', '$\frac{x^2-81}{x-9}=x+9,;x\ne9$.', 4), ('70000000-0000-4000-8000-000000962115', '40000000-0000-4000-8000-000000096211', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096212', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, partindo de $y=x^2$, qual transformação produz $g(x)=(x-9)^2+8$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962121', '40000000-0000-4000-8000-000000096212', 'A', 'Deslocar 9 unidades à direita e 8 para cima.', 1), ('50000000-0000-4000-8000-000000962122', '40000000-0000-4000-8000-000000096212', 'B', 'Deslocar 9 unidades à esquerda e 8 para cima.', 2), ('50000000-0000-4000-8000-000000962123', '40000000-0000-4000-8000-000000096212', 'C', 'Deslocar 8 unidades à direita e 9 para cima.', 3), ('50000000-0000-4000-8000-000000962124', '40000000-0000-4000-8000-000000096212', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096212', '50000000-0000-4000-8000-000000962121') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096212', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962121', '40000000-0000-4000-8000-000000096212', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962122', '40000000-0000-4000-8000-000000096212', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000962123', '40000000-0000-4000-8000-000000096212', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096212', 'Deslocar 9 unidades à direita e 8 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962121', '40000000-0000-4000-8000-000000096212', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962122', '40000000-0000-4000-8000-000000096212', 'Identifique a informação', '$g(x)=(x-9)^2+8$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000962123', '40000000-0000-4000-8000-000000096212', 'Escreva a condição', '$x-9$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000962124', '40000000-0000-4000-8000-000000096212', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(9,8)$.', 4), ('70000000-0000-4000-8000-000000962125', '40000000-0000-4000-8000-000000096212', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096213', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, para qual valor de $c$ a função $f(x)=\begin{cases}x+10,&x<10\\c,&x\ge10\end{cases}$ é contínua em $x=10$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962131', '40000000-0000-4000-8000-000000096213', 'A', '$20$', 1), ('50000000-0000-4000-8000-000000962132', '40000000-0000-4000-8000-000000096213', 'B', '$10$', 2), ('50000000-0000-4000-8000-000000962133', '40000000-0000-4000-8000-000000096213', 'C', '$21$', 3), ('50000000-0000-4000-8000-000000962134', '40000000-0000-4000-8000-000000096213', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096213', '50000000-0000-4000-8000-000000962131') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096213', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962131', '40000000-0000-4000-8000-000000096213', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962132', '40000000-0000-4000-8000-000000096213', 'Para haver continuidade, o limite pela esquerda deve coincidir com o valor da função.', 2), ('60000000-0000-4000-8000-000000962133', '40000000-0000-4000-8000-000000096213', 'A expressão da esquerda vale x mais 10.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096213', '$c=20$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962131', '40000000-0000-4000-8000-000000096213', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962132', '40000000-0000-4000-8000-000000096213', 'Identifique a informação', 'O possível salto ocorre no ponto $x=10$.', 2), ('70000000-0000-4000-8000-000000962133', '40000000-0000-4000-8000-000000096213', 'Escreva a condição', '$lim_{x\to10^-}(x+10)=10+10$.', 3), ('70000000-0000-4000-8000-000000962134', '40000000-0000-4000-8000-000000096213', 'Faça o cálculo', '$lim_{x\to10^-}f(x)=20$.', 4), ('70000000-0000-4000-8000-000000962135', '40000000-0000-4000-8000-000000096213', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096214', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, para $f(x)=-x^2+14x$, em qual x ocorre o máximo global?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962141', '40000000-0000-4000-8000-000000096214', 'A', '$x=7$', 1), ('50000000-0000-4000-8000-000000962142', '40000000-0000-4000-8000-000000096214', 'B', '$x=14$', 2), ('50000000-0000-4000-8000-000000962143', '40000000-0000-4000-8000-000000096214', 'C', '$x=-7$', 3), ('50000000-0000-4000-8000-000000962144', '40000000-0000-4000-8000-000000096214', 'D', '$x=0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
