insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096217', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962171', '40000000-0000-4000-8000-000000096217', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962172', '40000000-0000-4000-8000-000000096217', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000962173', '40000000-0000-4000-8000-000000096217', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096217', '$x=y=11$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962171', '40000000-0000-4000-8000-000000096217', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962172', '40000000-0000-4000-8000-000000096217', 'Use o perímetro', '$2x+2y=44 \Rightarrow y=22-x.$', 2), ('70000000-0000-4000-8000-000000962173', '40000000-0000-4000-8000-000000096217', 'Escreva a área', '$A(x)=x(22-x).$', 3), ('70000000-0000-4000-8000-000000962174', '40000000-0000-4000-8000-000000096217', 'Localize o vértice', '$A^{\prime}(x)=22-2x=0 \Rightarrow x=11, y=11.$', 4), ('70000000-0000-4000-8000-000000962175', '40000000-0000-4000-8000-000000096217', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096218', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Para conferir uma solução possível, se $f(x)=x(x+3)$, qual é $f^{\prime}(x)$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962181', '40000000-0000-4000-8000-000000096218', 'A', '$2x+3$', 1), ('50000000-0000-4000-8000-000000962182', '40000000-0000-4000-8000-000000096218', 'B', '$x+3$', 2), ('50000000-0000-4000-8000-000000962183', '40000000-0000-4000-8000-000000096218', 'C', '$2x$', 3), ('50000000-0000-4000-8000-000000962184', '40000000-0000-4000-8000-000000096218', 'D', '$x^2+3$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
