insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962301', '40000000-0000-4000-8000-000000096230', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962302', '40000000-0000-4000-8000-000000096230', 'Você pode expandir o produto ou aplicar a regra do produto.', 2), ('60000000-0000-4000-8000-000000962303', '40000000-0000-4000-8000-000000096230', 'A derivada de x é 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096230', '$f^{\prime}(x)=2x+4$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra do produto considera a variação dos dois fatores, por isso não basta derivar apenas um deles. Também é possível expandir primeiro e derivar termo a termo. As duas rotas chegam ao mesmo resultado e servem como verificação uma da outra; essa dupla leitura é útil para evitar esquecer uma parcela da derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962301', '40000000-0000-4000-8000-000000096230', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962302', '40000000-0000-4000-8000-000000096230', 'Observe a estrutura', '$f(x)=x^2+4x$', 2), ('70000000-0000-4000-8000-000000962303', '40000000-0000-4000-8000-000000096230', 'Escolha a regra', 'Use a regra da potência em cada termo.', 3), ('70000000-0000-4000-8000-000000962304', '40000000-0000-4000-8000-000000096230', 'Calcule', '$f^{\prime}(x)=2x+4$', 4), ('70000000-0000-4000-8000-000000962305', '40000000-0000-4000-8000-000000096230', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096231', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, calcule a derivada de $g(x)=(x^2+8)^3$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
