insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962331', '40000000-0000-4000-8000-000000096233', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962332', '40000000-0000-4000-8000-000000096233', 'Derive cada parcela do polinômio separadamente.', 2), ('60000000-0000-4000-8000-000000962333', '40000000-0000-4000-8000-000000096233', 'Depois de derivar, substitua x igual a 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096233', '$f^{\prime}(1)=11$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962331', '40000000-0000-4000-8000-000000096233', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962332', '40000000-0000-4000-8000-000000096233', 'Derive a potência', '$(x^2)^{\prime}=2x.$', 2), ('70000000-0000-4000-8000-000000962333', '40000000-0000-4000-8000-000000096233', 'Derive o termo linear', '$(9x)^{\prime}=9.$', 3), ('70000000-0000-4000-8000-000000962334', '40000000-0000-4000-8000-000000096233', 'Avalie em 1', '$f^{\prime}(1)=2+9=11.$', 4), ('70000000-0000-4000-8000-000000962335', '40000000-0000-4000-8000-000000096233', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096234', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, calcule $\lim_{x\to11}\frac{x^2-121}{x-11}$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962341', '40000000-0000-4000-8000-000000096234', 'A', '$22$', 1), ('50000000-0000-4000-8000-000000962342', '40000000-0000-4000-8000-000000096234', 'B', '$11$', 2), ('50000000-0000-4000-8000-000000962343', '40000000-0000-4000-8000-000000096234', 'C', '$122$', 3), ('50000000-0000-4000-8000-000000962344', '40000000-0000-4000-8000-000000096234', 'D', 'Não existe.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
