insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962351', '40000000-0000-4000-8000-000000096235', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962352', '40000000-0000-4000-8000-000000096235', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000962353', '40000000-0000-4000-8000-000000096235', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096235', 'Deslocar 11 unidades à direita e 10 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962351', '40000000-0000-4000-8000-000000096235', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962352', '40000000-0000-4000-8000-000000096235', 'Identifique a informação', '$g(x)=(x-11)^2+10$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000962353', '40000000-0000-4000-8000-000000096235', 'Escreva a condição', '$x-11$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000962354', '40000000-0000-4000-8000-000000096235', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(11,10)$.', 4), ('70000000-0000-4000-8000-000000962355', '40000000-0000-4000-8000-000000096235', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
