insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962371', '40000000-0000-4000-8000-000000096237', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962372', '40000000-0000-4000-8000-000000096237', 'Exponencie os dois lados com base e.', 2), ('60000000-0000-4000-8000-000000962373', '40000000-0000-4000-8000-000000096237', 'Lembre que o logaritmo natural só aceita entradas positivas.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096237', '$x=e^{10}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962371', '40000000-0000-4000-8000-000000096237', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962372', '40000000-0000-4000-8000-000000096237', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 2), ('70000000-0000-4000-8000-000000962373', '40000000-0000-4000-8000-000000096237', 'Escreva a condição', '$e^{\ln(x)}=e^{10}$.', 3), ('70000000-0000-4000-8000-000000962374', '40000000-0000-4000-8000-000000096237', 'Faça o cálculo', '$x=e^{10}$.', 4), ('70000000-0000-4000-8000-000000962375', '40000000-0000-4000-8000-000000096237', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096238', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, um retângulo tem perímetro 52 m. Qual deve ser a medida de cada lado para que sua área seja máxima?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962381', '40000000-0000-4000-8000-000000096238', 'A', '$13$ m', 1), ('50000000-0000-4000-8000-000000962382', '40000000-0000-4000-8000-000000096238', 'B', '$15$ m', 2), ('50000000-0000-4000-8000-000000962383', '40000000-0000-4000-8000-000000096238', 'C', '$10$ m', 3), ('50000000-0000-4000-8000-000000962384', '40000000-0000-4000-8000-000000096238', 'D', '$26$ m', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096238', '50000000-0000-4000-8000-000000962381') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096238', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962381', '40000000-0000-4000-8000-000000096238', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962382', '40000000-0000-4000-8000-000000096238', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000962383', '40000000-0000-4000-8000-000000096238', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096238', '$x=y=13$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962381', '40000000-0000-4000-8000-000000096238', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962382', '40000000-0000-4000-8000-000000096238', 'Use o perímetro', '$2x+2y=52 \Rightarrow y=26-x.$', 2), ('70000000-0000-4000-8000-000000962383', '40000000-0000-4000-8000-000000096238', 'Escreva a área', '$A(x)=x(26-x).$', 3), ('70000000-0000-4000-8000-000000962384', '40000000-0000-4000-8000-000000096238', 'Localize o vértice', '$A^{\prime}(x)=26-2x=0 \Rightarrow x=13, y=13.$', 4), ('70000000-0000-4000-8000-000000962385', '40000000-0000-4000-8000-000000096238', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096239', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, se $f(x)=x(x+5)$, qual é $f^{\prime}(x)$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000962391', '40000000-0000-4000-8000-000000096239', 'A', '$2x+5$', 1), ('50000000-0000-4000-8000-000000962392', '40000000-0000-4000-8000-000000096239', 'B', '$x+5$', 2), ('50000000-0000-4000-8000-000000962393', '40000000-0000-4000-8000-000000096239', 'C', '$2x$', 3), ('50000000-0000-4000-8000-000000962394', '40000000-0000-4000-8000-000000096239', 'D', '$x^2+5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
