insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000962431', '40000000-0000-4000-8000-000000096243', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000962432', '40000000-0000-4000-8000-000000096243', 'Uma parábola com coeficiente negativo em x ao quadrado abre para baixo.', 2), ('60000000-0000-4000-8000-000000962433', '40000000-0000-4000-8000-000000096243', 'Encontre o ponto em que a derivada se anula.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096243', '$x=10$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma função quadrática com coeficiente principal negativo tem concavidade voltada para baixo; por isso, seu único ponto crítico é um máximo global. A derivada permite localizar esse ponto sem depender de um esboço do gráfico e confirma onde a taxa de variação muda de positiva para negativa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000962431', '40000000-0000-4000-8000-000000096243', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000962432', '40000000-0000-4000-8000-000000096243', 'Derive', '$f^{\prime}(x)=-2x+20.$', 2), ('70000000-0000-4000-8000-000000962433', '40000000-0000-4000-8000-000000096243', 'Encontre o crítico', '$-2x+20=0 \Rightarrow x=10.$', 3), ('70000000-0000-4000-8000-000000962434', '40000000-0000-4000-8000-000000096243', 'Classifique', '$f^{primeprime}(x)=-2<0,$ portanto é máximo.', 4), ('70000000-0000-4000-8000-000000962435', '40000000-0000-4000-8000-000000096243', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096244', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, em qual valor de $x$ a função $f(x)=-(x-3)^2+2$ atinge seu máximo?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
