insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096249', '$x=2$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma parábola com sinal negativo abre para baixo, então seu vértice representa o maior valor possível. A forma quadrada mostra diretamente a posição horizontal do vértice: o quadrado é mínimo quando vale zero. Assim, maximizar a função equivale a escolher o valor de x que anula o termo entre parênteses. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
