-- Pacote calculo-1-renovado: parte 2 de 2.
-- Execute cada parte uma única vez, sempre em ordem numérica.
-- Não execute depois as migrations individuais já incorporadas aqui.
-- Pré-requisito: o schema base da Arc já deve existir.
-- Ordem segura dos conjuntos: calculo-2, calculo-1, calculo-vetorial.
-- ===== 202609091822000_diversify_calculus_1_batch_02.sql =====
-- Banco Cálculo I renovado — lote 02: 125 questões autorais revisadas.
-- Execute os lotes 01 e 02 antes da limpeza final.
begin;

values ('10000000-0000-4000-8000-000000000243', 'original', 'Arc original Cálculo I — banco renovado, lote 02', 'Questões autorais da Arc, revisadas para diversidade, clareza pedagógica e consistência matemática.', 'Arc', 'approved', 'Equipe editorial Arc', '2026-09-09T00:00:00Z')
on conflict (id) do update set label = excluded.label, licence_note = excluded.licence_note, rights_status = excluded.rights_status, verified_by = excluded.verified_by, verified_at = excluded.verified_at;






























































































































commit;

-- ===== 202609091823000_cleanup_superseded_calculus_1_drafts.sql =====
-- Limpeza final do banco anterior de Cálculo I.
-- Execute somente depois de importar os dois lotes renovados (250 questões).
-- A guarda abaixo impede uma exclusão parcial em caso de importação incompleta.

do $$
declare
  renewed_count integer;
begin
  select count(*) into renewed_count
  from public.questions
  where subject_id = '20000000-0000-4000-8000-000000000004'
    and publication_status = 'published'
    and source_id in (
      '10000000-0000-4000-8000-000000000242',
      '10000000-0000-4000-8000-000000000243'
    );

  if renewed_count <> 250 then
    raise exception 'Limpeza interrompida: esperadas 250 questões renovadas de Cálculo I; encontradas %.', renewed_count;
  end if;
end;
$$;

begin;

-- As tentativas dependem das questões antigas e precisam sair antes delas.
delete from public.question_attempts
where question_id in (
  select id from public.questions
  where subject_id = '20000000-0000-4000-8000-000000000004'
    and publication_status = 'draft'
);

delete from public.questions
where subject_id = '20000000-0000-4000-8000-000000000004'
  and publication_status = 'draft';

delete from public.question_sources
where label like 'Arc original Cálculo I%'
  and id not in (
    '10000000-0000-4000-8000-000000000242',
    '10000000-0000-4000-8000-000000000243'
  )
  and not exists (
    select 1 from public.questions where source_id = public.question_sources.id
  );

commit;
